package in.finseq.insurance;
import android.os.*;import android.widget.*;import org.json.*;import java.text.*;import java.util.*;
public class AttendanceSalaryActivity extends FinseqActivity{
 LinearLayout body;EditText month;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=Ui.column(this);Ui.appHeader(root,this,"Salary / Payable Days");body=Ui.contentColumn(this);root.addView(body);month=Ui.input(this,"YYYY-MM");month.setText(new SimpleDateFormat("yyyy-MM",Locale.US).format(new Date()));Button load=Ui.greenButton(this,"Load");load.setOnClickListener(v->load());body.addView(month);body.addView(load);Ui.setScreen(this,root,5);load();}
 void load(){final String m=month.getText().toString().trim();Ui.run(this,()->{try{JSONObject j=ApiClient.get(this,"/api/attendance/payroll?month="+m);Ui.ui(this,()->show(j));}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
 void show(JSONObject j){while(body.getChildCount()>2)body.removeViewAt(2);LinearLayout c=Ui.card(this);JSONObject p=j.optJSONObject("payroll");c.addView(Ui.text(this,j.optString("month")+" · "+(j.optBoolean("provisional")?"Provisional":"Locked"),19,true));c.addView(Ui.sub(this,"Monthly Salary: ₹"+String.format(Locale.US,"%.2f",j.optDouble("monthly_salary",0))+"\nPresent records: "+j.optInt("present_records")+" · Late: "+j.optInt("late_count")+" · Half-Day: "+j.optInt("half_day_count")+"\nWork minutes: "+j.optInt("work_minutes")));if(p!=null)c.addView(Ui.sub(this,"Scheduled days: "+p.optDouble("scheduled_working_days")+"\nPayable attendance days: "+p.optDouble("attendance_payable_days")+"\nAttendance pay: ₹"+String.format(Locale.US,"%.2f",p.optDouble("attendance_pay"))+"\nAttendance bonus: ₹"+String.format(Locale.US,"%.2f",p.optDouble("bonus_amount"))+"\nFinal: ₹"+String.format(Locale.US,"%.2f",j.optDouble("display_final_amount"))+"\nStatus: "+p.optString("status")));else c.addView(Ui.sub(this,"Payroll preview has not yet been calculated by Admin for this month."));body.addView(c);}
}